"""Host-generated bytecode must not affect published browser artifacts."""
import sys
import tempfile
import unittest
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parents[2] / 'scripts'))
from build_pages import copy_browser_sources


class BrowserStagingTests(unittest.TestCase):
    def test_excludes_generated_bytecode_and_tests_at_every_depth(self):
        with tempfile.TemporaryDirectory() as tmp:
            root = Path(tmp)
            source = root / 'web'
            files = ['index.html', '.nojekyll', 'python_bridge.py',
                     'assets/runtime.js', '__pycache__/python_bridge.cpython-312.pyc',
                     'assets/__pycache__/cached.pyc', 'orphan.pyc',
                     'tests/smoke.mjs', 'assets/tests/unit.mjs']
            for name in files:
                path = source / name
                path.parent.mkdir(parents=True, exist_ok=True)
                path.write_text('synthetic')
            copy_browser_sources(source, root / 'site')
            actual = {p.relative_to(root / 'site').as_posix()
                      for p in (root / 'site').rglob('*') if p.is_file()}
            self.assertEqual(actual, {'index.html', '.nojekyll', 'python_bridge.py',
                                      'assets/runtime.js'})
